bool8 HealStatusConditions(struct Pokemon *mon, u32 battlePartyId, u32 healMask, u8 battlerId)
{
    u32 status = GetMonData(mon, MON_DATA_STATUS, 0);

    if (status & healMask)
    {
        status &= ~healMask;
        SetMonData(mon, MON_DATA_STATUS, &status);
        if (gMain.inBattle && battlerId != MAX_BATTLERS_COUNT)
            gBattleMons[battlerId].status1 &= ~healMask;
        return FALSE;
    }
    else
    {
        return TRUE;
    }
}

u8 GetItemEffectParamOffset(u16 itemId, u8 effectByte, u8 effectBit)
{
    const u8 *temp;
    const u8 *itemEffect;
    u8 offset;
    int i;
    u8 j;
    u8 val;

    offset = 6;

    temp = gItemEffectTable[itemId];

    if (!temp && itemId != ITEM_ENIGMA_BERRY)
        return 0;

    if (itemId == ITEM_ENIGMA_BERRY)
    {
        temp = gEnigmaBerries[gActiveBattler].itemEffect;
    }

    itemEffect = temp;

    for (i = 0; i < 6; i++)
    {
        switch (i)
        {
        case 0:
        case 1:
        case 2:
        case 3:
            if (i == effectByte)
                return 0;
            break;
        case 4:
            val = itemEffect[4];
            if (val & ITEM4_PP_UP)
                val &= ~(ITEM4_PP_UP);
            j = 0;
            while (val)
            {
                if (val & 1)
                {
                    switch (j)
                    {
                    case 2:
                        if (val & 0x10)
                            val &= 0xEF;
                    case 0:
                        if (i == effectByte && (val & effectBit))
                            return offset;
                        offset++;
                        break;
                    case 1:
                        if (i == effectByte && (val & effectBit))
                            return offset;
                        offset++;
                        break;
                    case 3:
                        if (i == effectByte && (val & effectBit))
                            return offset;
                        offset++;
                        break;
                    case 7:
                        if (i == effectByte)
                            return 0;
                        break;
                    }
                }
                j++;
                val >>= 1;
                if (i == effectByte)
                    effectBit >>= 1;
            }
            break;
        case 5:
            val = itemEffect[5];
            j = 0;
            while (val)
            {
                if (val & 1)
                {
                    switch (j)
                    {
                    case 0:
                    case 1:
                    case 2:
                    case 3:
                    case 4:
                    case 5:
                    case 6:
                        if (i == effectByte && (val & effectBit))
                            return offset;
                        offset++;
                        break;
                    case 7:
                        if (i == effectByte)
                            return 0;
                        break;
                    }
                }
                j++;
                val >>= 1;
                if (i == effectByte)
                    effectBit >>= 1;
            }
            break;
        }
    }

    return offset;
}

static void BufferStatRoseMessage(s32 arg0)
{
    gBattlerTarget = gBattlerInMenuId;
    StringCopy(gBattleTextBuff1, gStatNamesTable[sStatsToRaise[arg0]]);
    StringCopy(gBattleTextBuff2, sText_StatSharply);
    StringAppend(gBattleTextBuff2, gText_StatRose);
    BattleStringExpandPlaceholdersToDisplayedString(gText_PkmnsStatChanged2);
}

u8 *UseStatIncreaseItem(u16 itemId)
{
    int i;
    const u8 *itemEffect;

    if (itemId == ITEM_ENIGMA_BERRY)
    {
        if (gMain.inBattle)
            itemEffect = gEnigmaBerries[gBattlerInMenuId].itemEffect;
        else
            //itemEffect = gSaveBlock1Ptr->enigmaBerry.itemEffect;
            itemEffect = 0;
    }
    else
    {
        itemEffect = gItemEffectTable[itemId];
    }

    gPotentialItemEffectBattler = gBattlerInMenuId;

    for (i = 0; i < 3; i++)
    {
        if (itemEffect[i] & (ITEM0_X_ATTACK | ITEM1_X_SPEED | ITEM2_X_SPATK))
            BufferStatRoseMessage(i * 2);

        if (itemEffect[i] & (ITEM0_DIRE_HIT | ITEM1_X_DEFEND | ITEM2_X_ACCURACY))
        {
            if (i != 0) // Dire Hit is the only ITEM0 above
            {
                BufferStatRoseMessage(i * 2 + 1);
            }
            else
            {
                gBattlerAttacker = gBattlerInMenuId;
                BattleStringExpandPlaceholdersToDisplayedString(gText_PkmnGettingPumped);
            }
        }
    }

    if (itemEffect[3] & ITEM3_GUARD_SPEC)
    {
        gBattlerAttacker = gBattlerInMenuId;
        BattleStringExpandPlaceholdersToDisplayedString(gText_PkmnShroudedInMist);
    }

    return gDisplayedStringBattle;
}

u8 GetNature(struct Pokemon *mon, bool32 checkHidden)
{
	if (!checkHidden || GetMonData(mon, MON_DATA_HIDDEN_NATURE, 0) == HIDDEN_NATURE_NONE || GetMonData(mon, MON_DATA_HIDDEN_NATURE, 0) == NATURE_HARDY)
        return GetNatureFromPersonality(GetMonData(mon, MON_DATA_PERSONALITY, 0));
    else
        return GetMonData(mon, MON_DATA_HIDDEN_NATURE, 0);
}

u8 GetNatureFromPersonality(u32 personality)
{
    return personality % NUM_NATURES;
}

u16 GetEvolutionTargetSpecies(struct Pokemon *mon, u8 type, u16 evolutionItem, u16 tradePartnerSpecies, u8 *targetFormId)
{
    int i, j;
    u16 targetSpecies = 0;
    u16 species = GetMonData(mon, MON_DATA_SPECIES, 0);
    u8 formId = GetMonData(mon, MON_DATA_FORM_ID, 0);
    u16 formSpeciesId = GetFormSpeciesId(species, formId);
    u16 heldItem = GetMonData(mon, MON_DATA_HELD_ITEM, 0);
    u32 personality = GetMonData(mon, MON_DATA_PERSONALITY, 0);
	u8 exioliteStatus = GetMonData(mon, MON_DATA_EXIOLITE_ENABLED, 0);
    u8 level;
    u16 friendship;
    u8 beauty = GetMonData(mon, MON_DATA_BEAUTY, 0);
    u16 upperPersonality = personality >> 16;
    u8 holdEffect;
    u16 currentMap;
    *targetFormId = 0;

    if (heldItem == ITEM_ENIGMA_BERRY)
        //holdEffect = gSaveBlock1Ptr->enigmaBerry.holdEffect;
        holdEffect = 0;
    else
        holdEffect = ItemId_GetHoldEffect(heldItem);
	
	if(FlagGet(FLAG_NO_EVOLUTION_MODE) || FlagGet(FLAG_FULL_RANDOMIZED_MODE))
		return SPECIES_NONE;

    if ((holdEffect == HOLD_EFFECT_PREVENT_EVOLVE && type != 3) || heldItem == ITEM_EVIOLITE || exioliteStatus == 1)
        return SPECIES_NONE;

    switch (type)
    {
    case 0:
        level = GetMonData(mon, MON_DATA_LEVEL, 0);
        friendship = GetMonData(mon, MON_DATA_FRIENDSHIP, 0);

        for (i = 0; i < EVOS_PER_MON; i++)
        {
            switch (gEvolutionTable[formSpeciesId][i].method)
            {
            case EVO_FRIENDSHIP:
                if (friendship >= 220)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_FRIENDSHIP_DAY:
                RtcCalcLocalTime();
                if (IsCurrentlyDay() && friendship >= 220)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_DUSK:
                RtcCalcLocalTime();
                if(IsCurrentlyDusk() && gEvolutionTable[formSpeciesId][i].param <= level)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_DAY:
                RtcCalcLocalTime();
                if (IsCurrentlyDay() && gEvolutionTable[formSpeciesId][i].param <= level && !(IsCurrentlyDusk() && formSpeciesId == SPECIES_ROCKRUFF))
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_NIGHT:
                RtcCalcLocalTime();
                if (!IsCurrentlyDay() && gEvolutionTable[formSpeciesId][i].param <= level && !(IsCurrentlyDusk() && formSpeciesId == SPECIES_ROCKRUFF))
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_FRIENDSHIP_NIGHT:
                RtcCalcLocalTime();
                if (!IsCurrentlyDay() && friendship >= 220)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_ITEM_HOLD_NIGHT:
                RtcCalcLocalTime();
                if (!IsCurrentlyDay() && heldItem == gEvolutionTable[formSpeciesId][i].param)
                {
                    heldItem = 0;
                    SetMonData(mon, MON_DATA_HELD_ITEM, &heldItem);
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_ITEM_HOLD_DAY:
                RtcCalcLocalTime();
                if (IsCurrentlyDay() && heldItem == gEvolutionTable[formSpeciesId][i].param)
                {
                    heldItem = 0;
                    SetMonData(mon, MON_DATA_HELD_ITEM, &heldItem);
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
			case EVO_LEVEL_SEVII:
                if (gEvolutionTable[formSpeciesId][i].param <= level && gMapHeader.region == REGION_SEVII)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
			case EVO_LEVEL_NOT_SEVII:
                if (gEvolutionTable[formSpeciesId][i].param <= level && gMapHeader.region != REGION_SEVII)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_FEMALE:
                if (gEvolutionTable[formSpeciesId][i].param <= level && GetMonGender(mon) == MON_FEMALE)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_MALE:
                if (gEvolutionTable[formSpeciesId][i].param <= level && GetMonGender(mon) == MON_MALE)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_ATK_GT_DEF:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                    if (GetMonData(mon, MON_DATA_ATK, 0) > GetMonData(mon, MON_DATA_DEF, 0))
                    {
                        *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                        targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                    }
                break;
            case EVO_LEVEL_ATK_EQ_DEF:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                    if (GetMonData(mon, MON_DATA_ATK, 0) == GetMonData(mon, MON_DATA_DEF, 0))
                    {
                        *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                        targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                    }
                break;
            case EVO_LEVEL_ATK_LT_DEF:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                    if (GetMonData(mon, MON_DATA_ATK, 0) < GetMonData(mon, MON_DATA_DEF, 0))
                    {
                        *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                        targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                    }
                break;
            case EVO_LEVEL_SILCOON:
                if (gEvolutionTable[formSpeciesId][i].param <= level && (upperPersonality % 10) <= 4)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_CASCOON:
                if (gEvolutionTable[formSpeciesId][i].param <= level && (upperPersonality % 10) > 4)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_NINJASK:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_BEAUTY:
                if (gEvolutionTable[formSpeciesId][i].param <= beauty)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_MOVE:
                if (MonKnowsMove(mon, gEvolutionTable[formSpeciesId][i].param))
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_MOVE_TYPE:
                for (j = 0; j < 4; j++)
                {
                    if (gBattleMoves[GetMonData(mon, MON_DATA_MOVE1 + j, NULL)].type == gEvolutionTable[formSpeciesId][i].param)
                    {
                        *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                        targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                        break;
                    }
                }
                break;
            case EVO_SPECIFIC_MON_IN_PARTY:
                for (j = 0; j < PARTY_SIZE; j++)
                {
                    if (GetMonData(&gPlayerParty[j], MON_DATA_SPECIES, NULL) == gEvolutionTable[formSpeciesId][i].param)
                    {
                        *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                        targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                        break;
                    }
                }
                break;
            case EVO_LEVEL_DARK_TYPE_MON_IN_PARTY:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                {
                    for (j = 0; j < PARTY_SIZE; j++)
                    {
                        u16 species = GetMonData(&gPlayerParty[j], MON_DATA_SPECIES, NULL);
                        u16 formId = GetMonData(&gPlayerParty[j], MON_DATA_FORM_ID, NULL);
                        u16 formSpeciesId = GetFormSpeciesId(species, formId);
                        if (gBaseStats[formSpeciesId].type1 == TYPE_DARK
                            || gBaseStats[formSpeciesId].type2 == TYPE_DARK)
                        {
                            *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                            targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                            break;
                        }
                    }
                }
                break;
            case EVO_LEVEL_RAIN:
                j = GetCurrentWeather();
                if (j == WEATHER_RAIN || j == WEATHER_RAIN_THUNDERSTORM || j == WEATHER_DOWNPOUR)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_MAPSEC:
                if (gMapHeader.regionMapSectionId == gEvolutionTable[formSpeciesId][i].param)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_SPECIFIC_MAP:
                currentMap = ((gSaveBlock1Ptr->location.mapGroup) << 8 | gSaveBlock1Ptr->location.mapNum);
                if (currentMap == gEvolutionTable[species][i].param)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_LEVEL_NIGHT_ALOLA:
                RtcCalcLocalTime();
				if (!IsCurrentlyDay() && gEvolutionTable[formSpeciesId][i].param <= level && gMapHeader.region == REGION_SEVII)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
			case EVO_VIVILLON:
                if (gEvolutionTable[formSpeciesId][i].param <= level)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
					
					if(targetSpecies == SPECIES_VIVILLON){				
						u16 PossibleEvo[] = {
							SPECIES_VIVILLON,
							SPECIES_VIVILLON_POLAR,
							SPECIES_VIVILLON_TUNDRA,
							SPECIES_VIVILLON_CONTINENTAL,
							SPECIES_VIVILLON_GARDEN,
							SPECIES_VIVILLON_ELEGANT,
							SPECIES_VIVILLON_MEADOW,
							SPECIES_VIVILLON_MODERN,
							SPECIES_VIVILLON_MARINE,
							SPECIES_VIVILLON_ARCHIPELAGO,
							SPECIES_VIVILLON_HIGH_PLAINS,
							SPECIES_VIVILLON_SANDSTORM,
							SPECIES_VIVILLON_RIVER,
							SPECIES_VIVILLON_MONSOON,
							SPECIES_VIVILLON_SAVANNA,
							SPECIES_VIVILLON_SUN,
							SPECIES_VIVILLON_OCEAN,
							SPECIES_VIVILLON_JUNGLE,
							//SPECIES_VIVILLON_FANCY,
							//SPECIES_VIVILLON_POKE_BALL,
						};
						
						
						targetSpecies = PossibleEvo[Random() % (sizeof(PossibleEvo)/sizeof(PossibleEvo[0]))];//
						
						*targetFormId = GetFormIdFromFormSpeciesId(targetSpecies);
						return targetSpecies;
					}
					else
						return SPECIES_NONE;
				}
				break;
				case EVO_TOXTRICITY:
				if (gEvolutionTable[species][i].param <= level)
                {
                    u8 nature = GetNature(mon, TRUE);
					if(gEvolutionTable[species][i].targetSpecies == SPECIES_TOXTRICITY){
						switch (nature)
						{
							case NATURE_HARDY:
							case NATURE_BRAVE:
							case NATURE_ADAMANT:
							case NATURE_NAUGHTY:
							case NATURE_DOCILE:
							case NATURE_IMPISH:
							case NATURE_LAX:
							case NATURE_HASTY:
							case NATURE_JOLLY:
							case NATURE_NAIVE:
							case NATURE_RASH:
							case NATURE_SASSY:
							case NATURE_QUIRKY:
								targetSpecies = SPECIES_TOXTRICITY;
								break;
							case NATURE_LONELY:
							case NATURE_BOLD:
							case NATURE_RELAXED:
							case NATURE_TIMID:
							case NATURE_SERIOUS:
							case NATURE_MODEST:
							case NATURE_MILD:
							case NATURE_QUIET:
							case NATURE_BASHFUL:
							case NATURE_CALM:
							case NATURE_GENTLE:
							case NATURE_CAREFUL:
								targetSpecies = SPECIES_TOXTRICITY_LOW_KEY;
								break;
						}
					}
                }
                break;
				case EVO_ALCREMIE:
				if (gEvolutionTable[formSpeciesId][i].param <= level)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
					
					if(targetSpecies == SPECIES_ALCREMIE){				
						u16 PossibleEvo[] = {
							SPECIES_ALCREMIE,
							SPECIES_ALCREMIE_RUBY_CREAM,
                            SPECIES_ALCREMIE_MATCHA_CREAM,
                            SPECIES_ALCREMIE_MINT_CREAM,
                            SPECIES_ALCREMIE_LEMON_CREAM,
                            SPECIES_ALCREMIE_SALTED_CREAM,
                            SPECIES_ALCREMIE_RUBY_SWIRL,
                            SPECIES_ALCREMIE_CARAMEL_SWIRL,
                            SPECIES_ALCREMIE_RAINBOW_SWIRL,
						};
						
						
						targetSpecies = PossibleEvo[Random() % (sizeof(PossibleEvo)/sizeof(PossibleEvo[0]))];//
						
						*targetFormId = GetFormIdFromFormSpeciesId(targetSpecies);
						return targetSpecies;
					}
					else
						return SPECIES_NONE;
				}
                break;
				case EVO_MELMETAL:
				if (gEvolutionTable[formSpeciesId][i].param <= level){
					for (j = 0; j < PARTY_SIZE; j++)
					{
						if (GetMonData(&gPlayerParty[j], MON_DATA_SPECIES, NULL) == SPECIES_MELTAN)
						{
							*targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
							targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
						}
						else
						return SPECIES_NONE;
					}
				}
                break;
				case EVO_HUSIAN:
				if (gEvolutionTable[formSpeciesId][i].param <= level)
					return SPECIES_NONE;
                break;
				case EVO_EXIOLITE:
				if(FlagGet(FLAG_LEVEL_EVO_ONLY)){
					if (gEvolutionTable[formSpeciesId][i].param <= level)
					{
						*targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
						targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
					}
				}
                break;
            }
        }
        break;
    case 1:
        for (i = 0; i < EVOS_PER_MON; i++)
        {
            switch (gEvolutionTable[formSpeciesId][i].method)
            {
            case EVO_TRADE:
                *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                break;
            case EVO_TRADE_ITEM:
                if (gEvolutionTable[formSpeciesId][i].param == heldItem)
                {
                    heldItem = 0;
                    SetMonData(mon, MON_DATA_HELD_ITEM, &heldItem);
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_TRADE_SPECIFIC_MON:
                if (gEvolutionTable[formSpeciesId][i].param == tradePartnerSpecies)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            }
        }
        break;
    case 2:
    case 3:
        for (i = 0; i < EVOS_PER_MON; i++)
        {
            switch (gEvolutionTable[formSpeciesId][i].method)
            {
            case EVO_ITEM:
                if (gEvolutionTable[formSpeciesId][i].param == evolutionItem)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_ITEM_FEMALE:
                if (GetMonGender(mon) == MON_FEMALE && gEvolutionTable[formSpeciesId][i].param == evolutionItem)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_ITEM_MALE:
                if (GetMonGender(mon) == MON_MALE && gEvolutionTable[formSpeciesId][i].param == evolutionItem)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            case EVO_ITEM_ALOLA:
                if (gEvolutionTable[formSpeciesId][i].param == evolutionItem && gMapHeader.region == REGION_SEVII)
                {
                    *targetFormId = GetFormIdFromFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies);
                    targetSpecies = GetFormSpeciesId(gEvolutionTable[formSpeciesId][i].targetSpecies, 0); // Get base species
                }
                break;
            }
        }
        break;
    }

    return targetSpecies;
}

u16 HoennPokedexNumToSpecies(u16 hoennNum)
{
    u16 species;

    if (!hoennNum)
        return 0;

    species = 0;

    while (species < (NUM_SPECIES - 1) && gSpeciesToHoennPokedexNum[species] != hoennNum)
        species++;

    if (species == NUM_SPECIES - 1)
        return 0;

    return species + 1;
}

u16 NationalPokedexNumToSpecies(u16 nationalNum)
{
    u16 species;

    if (!nationalNum)
        return 0;

    species = 0;

    while (species < (NUM_SPECIES - 1) && gSpeciesToNationalPokedexNum[species] != nationalNum)
        species++;

    if (species == NUM_SPECIES - 1)
        return 0;

    return species + 1;
}

u16 NationalToHoennOrder(u16 nationalNum)
{
    u16 hoennNum;

    if (!nationalNum)
        return 0;

    hoennNum = 0;

    while (hoennNum < (HOENN_DEX_COUNT - 1) && gHoennToNationalOrder[hoennNum] != nationalNum)
        hoennNum++;

    if (hoennNum >= HOENN_DEX_COUNT - 1)
        return 0;

    return hoennNum + 1;
}

u16 SpeciesToNationalPokedexNum(u16 species)
{
    if (!species)
        return 0;

    if (gFormSpeciesIdTables[species] != NULL)
        return gFormSpeciesIdTables[species][0];

    return gSpeciesToNationalPokedexNum[species - 1];
}

u16 SpeciesToHoennPokedexNum(u16 species)
{
    if (!species)
        return 0;

    return gSpeciesToHoennPokedexNum[species - 1];
}

u16 HoennToNationalOrder(u16 hoennNum)
{
    if (!hoennNum || hoennNum >= HOENN_DEX_COUNT)
        return 0;

    return gHoennToNationalOrder[hoennNum - 1];
}

void sub_806D544(u16 species, u32 personality, u8 *dest)
{
     if (species == SPECIES_YELTZER
        && dest != gMonSpritesGfxPtr->sprites[0]
        && dest != gMonSpritesGfxPtr->sprites[2])
    {
        int i;
        for (i = 0; i < 4; i++)
        {
            int j;
            u8 x = gSpindaSpotGraphics[i].x + ((personality & 0x0F) - 8);
            u8 y = gSpindaSpotGraphics[i].y + (((personality & 0xF0) >> 4) - 8);

            for (j = 0; j < 16; j++)
            {
                int k;
                s32 row = gSpindaSpotGraphics[i].image[j];

                for (k = x; k < x + 16; k++)
                {
                    u8 *val = dest + ((k / 8) * 32) + ((k % 8) / 2) + ((y >> 3) << 8) + ((y & 7) << 2);

                    if (row & 1)
                    {
                        if (k & 1)
                        {
                            if ((u8)((*val & 0xF0) - 0x10) <= 0x20)
                                *val += 0x40;
                        }
                        else
                        {
                            if ((u8)((*val & 0xF) - 0x01) <= 0x02)
                                *val += 0x04;
                        }
                    }

                    row >>= 1;
                }

                y++;
            }

            personality >>= 8;
        }
    }
}

