//TM Move Tutor --------------------------------------------------
u8 GetTMMovesPokemon(struct Pokemon *mon, u16 *Moves)
{
	u16 i, j;
	u16 learnedMoves[MAX_MON_MOVES];
	u8 movelimit = 45;
	u16 numMoves = 0;
	
	for (i = 0; i < MAX_MON_MOVES; i++)
        learnedMoves[i] = GetMonData(mon, MON_DATA_MOVE1 + i, 0);
	
	for (i = 0; i < 120; i++)
    {
		if(numMoves > movelimit)
			return numMoves;
		else if(CanMonLearnTMHM(mon, i) &&
				learnedMoves[0] != sTMHMMoves[i] &&
				learnedMoves[1] != sTMHMMoves[i] &&
				learnedMoves[2] != sTMHMMoves[i] &&
				learnedMoves[3] != sTMHMMoves[i]){
				Moves[numMoves] = sTMHMMoves[i];
				numMoves++;
		}
    }
    return numMoves;
}

u8 GetNumberOfTMMoves(struct Pokemon *mon)
{
	u16 i, j;
	u16 learnedMoves[MAX_MON_MOVES];
	u8 movelimit = 45;
	u16 numMoves = 0;
	
	for (i = 0; i < MAX_MON_MOVES; i++)
        learnedMoves[i] = GetMonData(mon, MON_DATA_MOVE1 + i, 0);
	
	for (i = 0; i < 120; i++)
    {
		if(numMoves > movelimit)
			return numMoves;
		else if(CanMonLearnTMHM(mon, i) &&
				learnedMoves[0] != sTMHMMoves[i] &&
				learnedMoves[1] != sTMHMMoves[i] &&
				learnedMoves[2] != sTMHMMoves[i] &&
				learnedMoves[3] != sTMHMMoves[i])
				numMoves++;
    }
    return numMoves;
}

//Move Relearner --------------------------------------------------
u8 GetMoveRelearnerMoves(struct Pokemon *mon, u16 *moves)
{
    u16 learnedMoves[4];
    u8 numMoves = 0;
    u16 species = GetMonData(mon, MON_DATA_SPECIES, 0);
	u16 firsStage = GetFirstEvolution(species);
    u8 formId = GetMonData(mon, MON_DATA_FORM_ID, 0);
    u16 formSpeciesId = GetFormSpeciesId(species, formId);
    u8 level = GetMonData(mon, MON_DATA_LEVEL, 0);
    int i, j, k;
	
	if(FlagGet(FLAG_LEVELESS_MODE))
		level = getGymLeaderMinLevel();

    for (i = 0; i < MAX_MON_MOVES; i++)
        learnedMoves[i] = GetMonData(mon, MON_DATA_MOVE1 + i, 0);

    for (i = 0; i < MAX_LEVEL_UP_MOVES; i++)
    {
        u16 moveLevel;

        if (gLevelUpLearnsets[formSpeciesId][i].move == LEVEL_UP_END)
            break;

        moveLevel = gLevelUpLearnsets[formSpeciesId][i].level;

        if (moveLevel <= level)
        {
            for (j = 0; j < MAX_MON_MOVES && learnedMoves[j] != gLevelUpLearnsets[formSpeciesId][i].move; j++)
                ;

            if (j == MAX_MON_MOVES)
            {
                for (k = 0; k < numMoves && moves[k] != gLevelUpLearnsets[formSpeciesId][i].move; k++)
                    ;

                if (k == numMoves)
                    moves[numMoves++] = gLevelUpLearnsets[formSpeciesId][i].move;
            }
        }
    }
    return numMoves;
}

u8 GetLevelUpMovesBySpecies(u16 species, u16 *moves, u8 formId)
{
    u16 formSpeciesId = GetFormSpeciesId(species, formId);
    u8 numMoves = 0;
    int i;

    for (i = 0; i < MAX_LEVEL_UP_MOVES && gLevelUpLearnsets[formSpeciesId][i].move != LEVEL_UP_END; i++)
         moves[numMoves++] = gLevelUpLearnsets[formSpeciesId][i].move;

    return numMoves;
}

