        case SPECIES_GOD_MEGA_Y:
            return MUS_RG_VS_GOD;
        case SPECIES_THEVOID:
            return MUS_VS_THEVOID;
        case SPECIES_SHOCKITTY:
            return HG_SEQ_GS_VS_SHOCKITTY;
        case SPECIES_HEATTAR:
            return HG_SEQ_GS_VS_HEATTAR;
        case SPECIES_REINGEER:
            return HG_SEQ_GS_VS_REINGEER;
        case SPECIES_HELPME:
            return HG_SEQ_GS_VS_HELPME;
        case SPECIES_SUFFER:
            return HG_SEQ_GS_VS_HOUOU;
        case SPECIES_LILGUY:
            return HG_SEQ_GS_VS_NORAPOKE;
        case SPECIES_BEERIO:
        case SPECIES_REGICE:
        case SPECIES_NAWFFLE:
        case SPECIES_REGIGIGAS:
        case SPECIES_REGIELEKI:
        case SPECIES_REGIDRAGO:
            return MUS_VS_REGI;
        case SPECIES_LATIAS:
        case SPECIES_LATIOS:
        case SPECIES_LATIAS_MEGA:
