u16 FacilityClassToPicIndex(u16 facilityClass)
{
    return gFacilityClassToPicIndex[facilityClass];
}

u16 PlayerGenderToFrontTrainerPicId(u8 playerGender)
{
    if (playerGender != MALE)
        return FacilityClassToPicIndex(FACILITY_CLASS_MAY);
    else
        return FacilityClassToPicIndex(FACILITY_CLASS_BRENDAN);
}

void HandleSetPokedexFlag(u16 nationalNum, u8 caseId, u32 personality)
{
    u8 getFlagCaseId = (caseId == FLAG_SET_SEEN) ? FLAG_GET_SEEN : FLAG_GET_CAUGHT;
    if (!GetSetPokedexFlag(nationalNum, getFlagCaseId)) // don't set if it's already set
    {
        GetSetPokedexFlag(nationalNum, caseId);
        if (NationalPokedexNumToSpecies(nationalNum) == SPECIES_UNOWN)
            gSaveBlock2Ptr->pokedex.unownPersonality = personality;
        if (NationalPokedexNumToSpecies(nationalNum) == SPECIES_FROSMOTH)
            gSaveBlock2Ptr->pokedex.yeltzerPersonality = personality;
    }
}

const u8 *GetTrainerClassNameFromId(u16 trainerId)
{
    if (trainerId >= TRAINERS_COUNT)
        trainerId = TRAINER_NONE;
    return gTrainerClassNames[gTrainers[trainerId].trainerClass];
}

const u8 *GetTrainerNameFromId(u16 trainerId)
{
    if (trainerId >= TRAINERS_COUNT)
        trainerId = TRAINER_NONE;
    return gTrainers[trainerId].trainerName;
}

bool8 HasTwoFramesAnimation(u16 species)
{
    return (species != SPECIES_UNOWN
            && species != SPECIES_UNOWN);
}

static bool8 ShouldSkipFriendshipChange(void)
{
    if (gMain.inBattle && gBattleTypeFlags & (BATTLE_TYPE_FRONTIER))
        return TRUE;
    if (!gMain.inBattle && (InBattlePike() || InBattlePyramid()))
        return TRUE;
    return FALSE;
}

static void sub_806F160(struct Unknown_806F160_Struct* structPtr)
{
    u16 i, j;
    for (i = 0; i < structPtr->field_0_0; i++)
    {
        structPtr->templates[i] = gUnknown_08329D98[i];
        for (j = 0; j < structPtr->field_1; j++)
        {
            structPtr->frameImages[i * structPtr->field_1 + j].data = &structPtr->byteArrays[i][j * 0x800];
        }
        structPtr->templates[i].images = &structPtr->frameImages[i * structPtr->field_1];
    }
}

static void sub_806F1FC(struct Unknown_806F160_Struct* structPtr)
{
    u16 i, j;
    for (i = 0; i < structPtr->field_0_0; i++)
    {
        structPtr->templates[i] = gUnknown_08329F28;
        for (j = 0; j < structPtr->field_1; j++)
        {
            structPtr->frameImages[i * structPtr->field_0_0 + j].data = &structPtr->byteArrays[i][j * 0x800];
        }
        structPtr->templates[i].images = &structPtr->frameImages[i * structPtr->field_0_0];
        structPtr->templates[i].anims = gUnknown_082FF70C;
        structPtr->templates[i].paletteTag = i;
    }
}

struct Unknown_806F160_Struct *sub_806F2AC(u8 id, u8 arg1)
{
    u8 i;
    u8 flags;
    struct Unknown_806F160_Struct *structPtr;

    flags = 0;
    id %= 2;
    structPtr = AllocZeroed(sizeof(*structPtr));
    if (structPtr == NULL)
        return NULL;

    switch (arg1)
    {
    case 2:
        structPtr->field_0_0 = 7;
        structPtr->field_0_1 = 7;
        structPtr->field_1 = 4;
        structPtr->field_3_0 = 1;
        structPtr->field_3_1 = 2;
        break;
    case 0:
    default:
        structPtr->field_0_0 = 4;
        structPtr->field_0_1 = 4;
        structPtr->field_1 = 4;
        structPtr->field_3_0 = 1;
        structPtr->field_3_1 = 0;
        break;
    }

    structPtr->bytes = AllocZeroed(structPtr->field_3_0 * 0x800 * 4 * structPtr->field_0_0);
    structPtr->byteArrays = AllocZeroed(structPtr->field_0_0 * 32);
    if (structPtr->bytes == NULL || structPtr->byteArrays == NULL)
    {
        flags |= 1;
    }
    else
    {
        for (i = 0; i < structPtr->field_0_0; i++)
            structPtr->byteArrays[i] = structPtr->bytes + (structPtr->field_3_0 * (i << 0xD));
    }

    structPtr->templates = AllocZeroed(sizeof(struct SpriteTemplate) * structPtr->field_0_0);
    structPtr->frameImages = AllocZeroed(sizeof(struct SpriteFrameImage) * structPtr->field_0_0 * structPtr->field_1);
    if (structPtr->templates == NULL || structPtr->frameImages == NULL)
    {
        flags |= 2;
    }
    else
    {
        for (i = 0; i < structPtr->field_1 * structPtr->field_0_0; i++)
            structPtr->frameImages[i].size = 0x800;

        switch (structPtr->field_3_1)
        {
        case 2:
            sub_806F1FC(structPtr);
            break;
        case 0:
        case 1:
        default:
            sub_806F160(structPtr);
            break;
        }
    }

    if (flags & 2)
    {
        if (structPtr->frameImages != NULL)
            FREE_AND_SET_NULL(structPtr->frameImages);
        if (structPtr->templates != NULL)
            FREE_AND_SET_NULL(structPtr->templates);
    }
    if (flags & 1)
    {
        if (structPtr->byteArrays != NULL)
            FREE_AND_SET_NULL(structPtr->byteArrays);
        if (structPtr->bytes != NULL)
            FREE_AND_SET_NULL(structPtr->bytes);
    }

    if (flags)
    {
        memset(structPtr, 0, sizeof(*structPtr));
        Free(structPtr);
    }
    else
    {
        structPtr->magic = 0xA3;
        gUnknown_020249B4[id] = structPtr;
    }

    return gUnknown_020249B4[id];
}

void sub_806F47C(u8 id)
{
    struct Unknown_806F160_Struct *structPtr;

    id %= 2;
    structPtr = gUnknown_020249B4[id];
    if (structPtr == NULL)
        return;

    if (structPtr->magic != 0xA3)
    {
        memset(structPtr, 0, sizeof(struct Unknown_806F160_Struct));
    }
    else
    {

        if (structPtr->frameImages != NULL)
            FREE_AND_SET_NULL(structPtr->frameImages);
        if (structPtr->templates != NULL)
            FREE_AND_SET_NULL(structPtr->templates);
        if (structPtr->byteArrays != NULL)
            FREE_AND_SET_NULL(structPtr->byteArrays);
        if (structPtr->bytes != NULL)
            FREE_AND_SET_NULL(structPtr->bytes);

        memset(structPtr, 0, sizeof(struct Unknown_806F160_Struct));
        Free(structPtr);
    }
}

u8 *sub_806F4F8(u8 id, u8 arg1)
{
    struct Unknown_806F160_Struct *structPtr = gUnknown_020249B4[id % 2];
    if (structPtr->magic != 0xA3)
    {
        return NULL;
    }
    else
    {
        if (arg1 >= structPtr->field_0_0)
            arg1 = 0;

        return structPtr->byteArrays[arg1];
    }
}

u16 MonTryLearningNewMoveEvolution(struct Pokemon *mon, bool8 firstMove)
{
    u16 species = GetMonData(mon, MON_DATA_SPECIES, NULL);
    u8 level = GetMonData(mon, MON_DATA_LEVEL, NULL);
	u8 formId = GetMonData(mon, MON_DATA_FORM_ID, NULL);
	u16 formSpeciesId = GetFormSpeciesId(species, formId);

    // since you can learn more than one move per level
    // the game needs to know whether you decided to
    // learn it or keep the old set to avoid asking
    // you to learn the same move over and over again
    if (firstMove)
    {
        sLearningMoveTableID = 0;
    }
    while(gLevelUpLearnsets[formSpeciesId][sLearningMoveTableID].move != LEVEL_UP_END)
    {
        u16 moveLevel;
        moveLevel = (gLevelUpLearnsets[formSpeciesId][sLearningMoveTableID].level);
        while (moveLevel == 0 || moveLevel == (level << 9))
        {
            gMoveToLearn = (gLevelUpLearnsets[formSpeciesId][sLearningMoveTableID].move);
            sLearningMoveTableID++;
            return GiveMoveToMon(mon, gMoveToLearn);
        }
        sLearningMoveTableID++;
    }
    return 0;
}

void CreateShinyMonWithNature(struct Pokemon *mon, u16 species, u8 level, u8 nature)
{
    u32 personality;
    u32 otid = gSaveBlock2Ptr->playerTrainerId[0]
              | (gSaveBlock2Ptr->playerTrainerId[1] << 8)
              | (gSaveBlock2Ptr->playerTrainerId[2] << 16)
              | (gSaveBlock2Ptr->playerTrainerId[3] << 24);

    do
    {
        personality = Random32();
        personality = ((((Random() % 8) ^ (HIHALF(otid) ^ LOHALF(otid))) ^ LOHALF(personality)) << 16) | LOHALF(personality);
    } while (nature != GetNatureFromPersonality(personality));
    CreateMon(mon, species, level, 32, 1, personality, OT_ID_PRESET, otid, 0);
}

u16 GetFormSpeciesId(u16 baseSpeciesId, u8 formId)
{
    if(gFormSpeciesIdTables[baseSpeciesId] != NULL)
        return gFormSpeciesIdTables[baseSpeciesId][formId];
    else
        return baseSpeciesId;
}

u8 GetFormIdFromFormSpeciesId(u16 formSpeciesId)
{
    u8 targetFormId = 0;
    
    if (gFormSpeciesIdTables[formSpeciesId] != NULL)
    {
        while (gFormSpeciesIdTables[formSpeciesId][targetFormId] != 0xFFFF)
        {
            if (formSpeciesId == gFormSpeciesIdTables[formSpeciesId][targetFormId])
                break;
            targetFormId++;
        }
    }
    return targetFormId;
}

u16 GetBaseFormSpeciesId(u16 formSpeciesId)
{
    if (gFormSpeciesIdTables[formSpeciesId] != NULL)
    {
        return gFormSpeciesIdTables[formSpeciesId][0];
    }
    return formSpeciesId;
}

bool8 SpeciesHasType(u16 species, u8 type)
{
	if(!FlagGet(FLAG_VANILLA_MODE)){
        if(gBaseStats[species].type1 == type || gBaseStats[species].type2 == type)
            return TRUE;
        else
            return FALSE;
	}else{
		if(gVanillaBaseStats[species].type1 == type || gVanillaBaseStats[species].type2 == type)
            return TRUE;
        else
            return FALSE;
	}
}

u16 GetRandomFirstStage(u16 basespecies){
	u16 num;
	u16 species;
	u16 rndSeed = VarGet(VAR_RANDOMIZED_SEED);
    
    if(rndSeed == 0){
        u16 newseed = Random() % 9999;
        VarSet(VAR_RANDOMIZED_SEED, newseed);
        rndSeed = VarGet(VAR_RANDOMIZED_SEED);
    }

    if(basespecies == SPECIES_HELIOPTILE || basespecies == SPECIES_HELIOLISK)
        return basespecies;
	else if(basespecies != SPECIES_NONE)
		num = (basespecies*rndSeed) % POKEMON_FAMILIES;
	else
		num = Random() % POKEMON_FAMILIES;
	
	return gFirstStageTable[num].species;
}

u16 GetGrowthRate(u16 formSpeciesId)
{
	if(!FlagGet(FLAG_FULL_RANDOMIZED_MODE))
		return formSpeciesId;
	else
		return SPECIES_MEADOSAUR;
}

u16 getBaseForm(u16 species){
    if(species <= FORMS_START)
        return species;
    else
        return gBaseFormID[species];
}

#define NUM_OUTBREAK_DAYS 1
#define NUM_CLEAN_EWRAM_DATA 0
void SetOutBreakPokemonFromCompanion(void){
    u16 species     = *(u32 *)(EWRAM_START + 0x3ffc0);
    u16 mapnum      = *(u32 *)(EWRAM_START + 0x3ffb0);
    u16 mapgroup    = *(u32 *)(EWRAM_START + 0x3ffa0);
    u8  level       = *(u32 *)(EWRAM_START + 0x3fef0);
    u8  badges      = *(u32 *)(EWRAM_START + 0x3fee0);
    u8  probability = *(u32 *)(EWRAM_START + 0x3fed0);
    u16  move1       = *(u32 *)(EWRAM_START + 0x3fec0);

    if(GetNumBadges() >= badges && species != 0){
        gSaveBlock1Ptr->outbreakPokemonSpecies     = species;
        gSaveBlock1Ptr->outbreakLocationMapNum     = mapnum;
        gSaveBlock1Ptr->outbreakLocationMapGroup   = mapgroup;
        gSaveBlock1Ptr->outbreakPokemonMoves[0]    = move1;
        gSaveBlock1Ptr->outbreakPokemonMoves[1]    = MOVE_NONE;
        gSaveBlock1Ptr->outbreakPokemonMoves[2]    = MOVE_NONE;
        gSaveBlock1Ptr->outbreakPokemonMoves[3]    = MOVE_NONE;
        gSaveBlock1Ptr->outbreakPokemonProbability = probability;
        gSaveBlock1Ptr->outbreakDaysLeft           = NUM_OUTBREAK_DAYS;

        if(level == 0)
            gSaveBlock1Ptr->outbreakPokemonLevel   = getWildPokemonLevel(); //Level Scaled
        else
            gSaveBlock1Ptr->outbreakPokemonLevel   = level;

        gSaveBlock1Ptr->outbreakUnk1 = 0;
        gSaveBlock1Ptr->outbreakUnk2 = 0;
        gSaveBlock1Ptr->outbreakUnk4 = 0;

        //Clear Data
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3ffc0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3ffb0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3ffa0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fef0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fee0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fed0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fec0, 0x2);
    }
}

void SetRoamerPokemonFromCompanion(void){
    u16 species     = *(u32 *)(EWRAM_START + 0x3feb0);
    u8  level       = *(u32 *)(EWRAM_START + 0x3fea0);
    u16 num         = *(u32 *)(EWRAM_START + 0x3fdf0);
    u16 badges      = *(u32 *)(EWRAM_START + 0x3fde0);
    if(GetNumBadges() >= badges && 
       species != 0 && 
       VarGet(VAR_LAST_ROAMER_NUM) != num &&
       gSaveBlock2Ptr->roamerFlag[num] == FALSE){
        VarSet(VAR_LAST_ROAMER_NUM, num);
        CreateOnlineRoamer(species, level);

        //Clear Data
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3feb0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fea0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fdf0, 0x2);
        DmaFill16(3, NUM_CLEAN_EWRAM_DATA, EWRAM_START + 0x3fde0, 0x2);
    }
}

u8 RandomizePokemonType(u8 type, u32 personality, bool8 isSecondtype){
    u8 randomizedType = TYPE_MYSTERY;

    if(!FlagGet(FLAG_TYPE_RANDOMIZER_MODE))
        return type;

    if(isSecondtype)
        randomizedType = (type + personality) % NUMBER_OF_MON_TYPES;
    else
        randomizedType = (personality - type ) % NUMBER_OF_MON_TYPES;

    do{
        randomizedType++;
        randomizedType = randomizedType % NUMBER_OF_MON_TYPES;
    }
    while(randomizedType == TYPE_MYSTERY || randomizedType == type);

    return randomizedType;
}

u8 GetThirdTypeFromPersonality(u32 personality, u16 type1, u16 type2){
    u8 randomizedType = TYPE_MYSTERY;

    if(!FlagGet(FLAG_THIRD_TYPE_MODE))
        return TYPE_MYSTERY;

    randomizedType = personality % NUMBER_OF_MON_TYPES;

    do{
        randomizedType++;
        randomizedType = randomizedType % NUMBER_OF_MON_TYPES;
    }
    while(randomizedType == TYPE_MYSTERY || randomizedType == type1 || randomizedType == type2);

    return randomizedType;
}

u16 RandomizePokemonAbility(u16 ability, u32 personality){
    if(!FlagGet(FLAG_ABILITY_RANDOMIZER_MODE))
        return ability;

    if(ability != ABILITY_NONE              &&
       ability != ABILITY_ZEN_MODE          &&
       ability != ABILITY_WONDER_GUARD      &&
       ability != ABILITY_POWER_CONSTRUCT   &&
       ability != ABILITY_SCHOOLING         &&
       ability != ABILITY_MULTITYPE         &&
       ability != ABILITY_FORECAST          &&
       ability != ABILITY_STANCE_CHANGE     &&
       ability != ABILITY_RKS_SYSTEM        &&
       ability != ABILITY_BATTLE_BOND       &&
       ability != ABILITY_POWER_CONSTRUCT   &&
       ability != ABILITY_ICE_FACE          &&
       ability != ABILITY_GULP_MISSILE      &&
       ability != ABILITY_DISGUISE          &&
       ability != ABILITY_FLOWER_GIFT       &&
       ability != ABILITY_PRIMORDIAL_SEA    &&
       ability != ABILITY_DELTA_STREAM      &&
       ability != ABILITY_DESOLATE_LAND     &&
       ability != ABILITY_HUNGER_SWITCH){ 
        //Only Randomize if you have the Ability Randomized Mode Enabled
        //Exclude form change abilities from being randomized and other mons can't get them either
        u16 randomizedAbility = (ability + personality) % ABILITIES_COUNT;
        do{
            randomizedAbility++;
            randomizedAbility = randomizedAbility % ABILITIES_COUNT;
        }
        while(randomizedAbility == ABILITY_NONE            ||
              randomizedAbility == ABILITY_HUGE_POWER      ||
              randomizedAbility == ABILITY_PURE_POWER      ||
              randomizedAbility == ABILITY_FELINE_PROWESS  ||
              randomizedAbility == ABILITY_HUNGER_SWITCH   ||
              randomizedAbility == ABILITY_ZEN_MODE        ||
              randomizedAbility == ABILITY_WONDER_GUARD    ||
              randomizedAbility == ABILITY_POWER_CONSTRUCT ||
              randomizedAbility == ABILITY_SCHOOLING       ||
              randomizedAbility == ABILITY_TRACE           ||
              randomizedAbility == ABILITY_TRUANT          ||
              randomizedAbility == ABILITY_MULTITYPE       ||
              randomizedAbility == ABILITY_FORECAST        ||
              randomizedAbility == ABILITY_DISGUISE        ||
              randomizedAbility == ABILITY_STANCE_CHANGE   ||
              randomizedAbility == ABILITY_COMATOSE        ||
              randomizedAbility == ABILITY_RKS_SYSTEM      ||
              randomizedAbility == ABILITY_BATTLE_BOND     ||
              randomizedAbility == ABILITY_POWER_CONSTRUCT ||
              randomizedAbility == ABILITY_FLOWER_GIFT     ||
              randomizedAbility == ABILITY_ICE_FACE        ||
              randomizedAbility == ABILITY_PRIMORDIAL_SEA  ||
              randomizedAbility == ABILITY_DELTA_STREAM    ||
              randomizedAbility == ABILITY_DESOLATE_LAND   ||
              randomizedAbility == ABILITY_WIMP_OUT        ||
              randomizedAbility == ABILITY_EMERGENCY_EXIT  ||
              randomizedAbility == ABILITY_GULP_MISSILE);
        return randomizedAbility;
    }
}
